-- Generated by scripts/build_seed.py; do not edit by hand.
-- Clearer categories: 8 source categories -> 13 display categories (see api/engine/categories.py),
-- plus ingredients added since (Burger Buns). Safe to run more than once. Nothing is deleted except
-- old category rows that are left empty; pantry, saved recipes and recipe lines are untouched.
begin;
insert into public.categories(name) values ('Meat & Poultry') on conflict (name) do nothing;
insert into public.categories(name) values ('Fish & Seafood') on conflict (name) do nothing;
insert into public.categories(name) values ('Vegetables') on conflict (name) do nothing;
insert into public.categories(name) values ('Fresh Herbs') on conflict (name) do nothing;
insert into public.categories(name) values ('Fruits') on conflict (name) do nothing;
insert into public.categories(name) values ('Dairy & Eggs') on conflict (name) do nothing;
insert into public.categories(name) values ('Grains & Flours') on conflict (name) do nothing;
insert into public.categories(name) values ('Bakery & Baking') on conflict (name) do nothing;
insert into public.categories(name) values ('Pulses & Lentils') on conflict (name) do nothing;
insert into public.categories(name) values ('Nuts, Seeds & Dry Fruits') on conflict (name) do nothing;
insert into public.categories(name) values ('Spices & Masalas') on conflict (name) do nothing;
insert into public.categories(name) values ('Sauces & Condiments') on conflict (name) do nothing;
insert into public.categories(name) values ('Oils, Ghee & Sweeteners') on conflict (name) do nothing;

-- New ingredients (existing rows are left exactly as they are).
insert into public.ingredients(name, category_id, kcal, protein, carbs, fat, sweet, salty, sour, spicy, allergens, priority) values ('Burger Buns (Bun)', (select id from public.categories where name = 'Bakery & Baking'), 279, 9.7, 49, 4.3, 2, 2, 0, 0, array['gluten']::text[], 3) on conflict (name) do nothing;

