-- Ingredients an admin added to an old category: its closest display category.
update public.ingredients set category_id = (select id from public.categories where name = 'Meat & Poultry') where category_id = (select id from public.categories where name = 'Meat');
update public.ingredients set category_id = (select id from public.categories where name = 'Dairy & Eggs') where category_id = (select id from public.categories where name = 'Dairy');
update public.ingredients set category_id = (select id from public.categories where name = 'Grains & Flours') where category_id = (select id from public.categories where name = 'Grocery');
update public.ingredients set category_id = (select id from public.categories where name = 'Spices & Masalas') where category_id = (select id from public.categories where name = 'Spices');
update public.ingredients set category_id = (select id from public.categories where name = 'Nuts, Seeds & Dry Fruits') where category_id = (select id from public.categories where name = 'Pulses & Nuts');
update public.ingredients set category_id = (select id from public.categories where name = 'Sauces & Condiments') where category_id = (select id from public.categories where name = 'Oils & Sauces');
delete from public.categories c where c.name in ('Meat', 'Dairy', 'Grocery', 'Spices', 'Pulses & Nuts', 'Oils & Sauces')
  and not exists (select 1 from public.ingredients i where i.category_id = c.id);
commit;
